CREATE TRIGGER order_history_immutable_update BEFORE UPDATE ON sales_order_revision BEGIN SELECT RAISE(ABORT,'ORDER_HISTORY_IMMUTABLE');END;
CREATE TRIGGER order_history_immutable_delete BEFORE DELETE ON sales_order_revision BEGIN SELECT RAISE(ABORT,'ORDER_HISTORY_IMMUTABLE');END;
CREATE TRIGGER plan_history_immutable_update BEFORE UPDATE ON work_plan_revision BEGIN SELECT RAISE(ABORT,'PLAN_HISTORY_IMMUTABLE');END;
CREATE TRIGGER plan_history_immutable_delete BEFORE DELETE ON work_plan_revision BEGIN SELECT RAISE(ABORT,'PLAN_HISTORY_IMMUTABLE');END;
